/* ============================================================
   أطياب الجاسم (React) — بطاقات التواصل (ContactUsNow) — v6

   تعرض كل قنوات ATYAB_CONTACT (واتساب · إنستغرام · تيك توك ·
   سناب شات) بالأيقونات الرسمية المملوءة من Icons.jsx، مع زر نسخ.
   الروابط الخارجية تُفتح في تبويب جديد.
   ============================================================ */

import { ATYAB_CONTACT } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { T, tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";

function iconFor(key) {
  if (key === "whatsapp") return "whatsapp";
  if (key === "instagram") return "instagram";
  if (key === "tiktok") return "tiktok";
  if (key === "snapchat") return "snapchat";
  if (key === "email") return "email";
  if (key === "phone" || key === "call") return "phone";
  return "chat";
}

function isBrand(key) {
  return key === "whatsapp" || key === "instagram" || key === "tiktok" || key === "snapchat";
}

export default function ContactUsNow(props) {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  const channels = props.channels || (ATYAB_CONTACT && ATYAB_CONTACT.channels) || [];

  function copy(value) {
    const done = function (ok) {
      const msg = ok
        ? tr2(language, "Copied \u00ab", "تم نسخ \u00ab") + value + "\u00bb"
        : tr2(language, "Could not copy \u2014 copy it manually: ", "تعذ\u0651ر النسخ \u2014 انسخه يدوي\u0627\u064b: ") + value;
      dispatch(uiActions.toastShown(msg));
    };
    const fallback = function () {
      try {
        const ta = document.createElement("textarea");
        ta.value = value;
        ta.setAttribute("readonly", "");
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        const ok = document.execCommand("copy");
        document.body.removeChild(ta);
        return ok;
      } catch (e) {
        return false;
      }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(value).then(
        function () { done(true); },
        function () { done(fallback()); }
      );
      return;
    }
    done(fallback());
  }

  return (
    <div className="cx-grid">
      {channels.map(function (ch) {
        const href = ch.href || "#";
        const external = /^https?:/i.test(href);
        const ic = iconFor(ch.key);
        const brand = isBrand(ch.key);
        const icEl = brand
          ? <Icon name={ic} />
          : <Icon name={ic} strokeWidth={1.7} />;
        return (
          <article className="cx-card" data-ch={ch.key} key={ch.key}>
            <span className="cx-ic">{icEl}</span>
            <div className="cx-card-head">
              <h2>{T(ch.label, language)}</h2>
              <span className="cx-en" dir="ltr">
                {language === "en" ? "" : ch.latin || ""}
              </span>
            </div>
            <p className="cx-handle" dir="ltr">
              {ch.handle}
            </p>
            <p className="cx-note">{T(ch.note, language)}</p>
            {/* ★ R16: سطر الساعة يُرسم فقط إن أضاف معلومة (واتساب) —
               سطور «تابعنا وشاركنا رأيك» المكررة حُذفت من البيانات */}
            {T(ch.reply, language) ? (
            <ul className="cx-meta">
              <li>
                <Icon name="clock" strokeWidth={1.8} />
                <span>{T(ch.reply, language)}</span>
              </li>
            </ul>
            ) : null}
            <div className="cx-actions">
              <a
                className="cx-go"
                href={href}
                target={external ? "_blank" : undefined}
                rel={external ? "noreferrer" : undefined}
              >
                {icEl}
                <span>{T(ch.action, language)}</span>
              </a>
              <button
                className="cx-copy"
                type="button"
                aria-label={tr2(language, "Copy ", "انسخ ") + T(ch.label, language)}
                title={tr2(language, "Copy", "انسخ")}
                onClick={function () { copy(ch.value); }}
              >
                <Icon name="copy" strokeWidth={1.7} />
              </button>
            </div>
          </article>
        );
      })}
    </div>
  );
}
