/* ============================================================
   أطياب الجاسم (React) — صفحة تواصل معنا (ContactUs)

   الصفحة جاهزة كما هي: العنوان والوصف، ثم بطاقات التواصل
   (واتساب · إيميل) عبر الكومبوننت ContactUsNow، ثم أوقات التواصل
   وعنوان المعرض، ثم «نحن هنا من أجلك في:» وقائمة المواضيع، وأخيراً
   بطاقة الشكر (مكتوبة هنا مباشرة — لا داعي لجعلها كومبوننت).

   ★ كل النصوص من ATYAB_CONTACT في ملف البيانات.
   ============================================================ */

import { Link } from "react-router-dom";
import { PATHS } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_CONTACT } from "../data/appConfig.js";
import { useAppSelector } from "../redux/hooks.js";
import { T, tr2 } from "../i18n.js";
import ContactUsNow from "../components/UserExperience/ContactUsNow.jsx";
import { Icon } from "../components/Source/Icons.jsx";

export default function ContactUs() {
  usePageMeta({ route: "contact", titleAr: "تواصل معنا", titleEn: "Contact us" });

  const C = ATYAB_CONTACT || {};
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  return (
    <section className="container view cx" id="contactView">
      <div className="cx-top">
        <Link className="cx-back" to={PATHS.perfumes}>
          <Icon name="back" strokeWidth={2} />
          <span>متابعة التسوق</span>
        </Link>
        <span className="cx-crumb">
          {tr2(language, "Home /", "الرئيسية /")} <b>{tr2(language, "Contact us", "تواصل معنا")}</b>
        </span>
      </div>

      <header className="cx-hero">
        <span className="eyebrow">{T(C.eyebrow, language)}</span>
        <h1>
          {T(C.title, language)} <span className="gold-text">{T(C.titleGold, language)}</span>
        </h1>
        <p className="cx-lead">{T(C.lead, language)}</p>
        <p className="cx-text">{T(C.text, language)}</p>
      </header>

      <div className="cx-info">
        <div className="cx-info-col">
          <h3>
            <Icon name="clock" strokeWidth={1.8} />
            <span>{T(C.hoursTitle, language)}</span>
          </h3>
          <ul className="cx-hours">
            {(C.hours || []).map(function (row) {
              return (
                <li key={row.key || T(row.label, "ar")}>
                  <span>{T(row.label, language)}</span>
                  <b>{T(row.value, language)}</b>
                </li>
              );
            })}
          </ul>
        </div>

        <div className="cx-info-col">
          <h3>
            <Icon name="pin" strokeWidth={1.8} />
            <span>{T(C.showroomTitle, language)}</span>
          </h3>
          <p className="cx-address">{T(C.address, language)}</p>
          <p className="cx-address-sub">{T(C.addressSub, language)}</p>
        </div>
      </div>

      <ContactUsNow />

            <div className="cx-topics">
        <span className="cx-topics-label">{T(C.topicsLabel, language)}</span>
        <ul className="cx-topics-list">
          {(C.topics || []).map(function (topic) {
            return <li key={topic.key}>{T(topic.label, language)}</li>;
          })}
        </ul>
      </div>

      {/* بطاقة الشكر — نصّها من البيانات، ومكتوبة هنا لا ككومبوننت */}
      <div className="cx-thanks">
        <span className="cx-thanks-ic">
          <Icon name="heart" strokeWidth={1.8} />
        </span>
        <h2>{C.thanks ? T(C.thanks.title, language) : tr2(language, "Thank you", "شكراً لك")}</h2>
        <p>{C.thanks ? T(C.thanks.text, language) : ""}</p>
        <p className="cx-sign">
          {C.thanks ? T(C.thanks.sign, language) : ""} <Icon name="star" fill="currentColor" strokeWidth={0} />
        </p>
        <div className="cx-thanks-actions">
          <Link className="btn-primary" to={PATHS.perfumes}>
            تصفّح العطور
          </Link>
          <Link className="btn-ghost" to={PATHS.incense}>
            تصفّح البخور
          </Link>
        </div>
      </div>
    </section>
  );
}
